package com.campus.identity.application;
import com.campus.common.error.ApiException;import com.campus.common.security.AuthSettings;import com.campus.identity.infrastructure.IdentityAuditOutbox;
import java.net.URI;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.security.*;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import java.time.*;import java.util.*;
import org.springframework.beans.factory.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.transaction.PlatformTransactionManager;
import tools.jackson.databind.JsonNode;import tools.jackson.databind.json.JsonMapper;
@Service
public class NotificationEmailService {
 private static final JsonMapper JSON=JsonMapper.builder().build();private static final SecureRandom RANDOM=new SecureRandom();
 private final JdbcTemplate jdbc;private final Clock clock;private final AuthSettings auth;private final IdentityAuditOutbox audit;private final TransactionTemplate tx;private final URI endpoint;
 private final HttpClient client=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).build();
 public NotificationEmailService(JdbcTemplate jdbc,@Qualifier("identityClock") Clock clock,AuthSettings auth,IdentityAuditOutbox audit,PlatformTransactionManager transactions,@Value("${campus.identity.notification-url:${campus.reservation.notification-url:http://workflow:8081/internal/notifications/events}}") String url){this.jdbc=jdbc;this.clock=clock;this.auth=auth;this.audit=audit;this.tx=new TransactionTemplate(transactions);this.endpoint=URI.create(url).resolve("/internal/notifications/verification-email");if(!Set.of("http","https").contains(endpoint.getScheme())||endpoint.getUserInfo()!=null)throw new IllegalArgumentException("Invalid notification endpoint");}
 public record Profile(String email,boolean verified,Instant verifiedAt,Instant pendingVerificationExpiresAt,String deliveryStatus,String deliveryErrorCode){}
 public Profile profile(UUID user){return jdbc.queryForObject("SELECT u.email,u.email_verified_at,c.expires_at,c.delivery_status,c.delivery_error FROM iam.users u LEFT JOIN LATERAL (SELECT expires_at,delivery_status,delivery_error FROM iam.email_verification_challenges WHERE user_id=u.id AND email_version=u.email_version ORDER BY issued_at DESC LIMIT 1)c ON true WHERE u.id=?",(r,n)->new Profile(r.getString("email"),r.getTimestamp("email_verified_at")!=null,instant(r.getTimestamp("email_verified_at")),instant(r.getTimestamp("expires_at")),r.getString("delivery_status"),r.getString("delivery_error")),user);}
 private static Instant instant(java.sql.Timestamp v){return v==null?null:v.toInstant();}
 public Profile save(UUID user,String email){String value=normalize(email);return tx.execute(status->{var row=jdbc.queryForMap("SELECT email FROM iam.users WHERE id=? FOR UPDATE",user);if(!Objects.equals(value,row.get("email"))){jdbc.update("UPDATE iam.users SET email=?,email_verified_at=NULL,email_version=email_version+1,updated_at=now() WHERE id=?",value,user);audit.enqueue("EMAIL_CHANGED",user,Map.of("hasEmail",row.get("email")!=null),Map.of("hasEmail",true,"verified",false));}return profile(user);});}
 private static String normalize(String value){if(value==null||value.length()>254||value.indexOf('@')<=0||value.chars().anyMatch(c->Character.isWhitespace(c)||Character.isISOControl(c)))throw new ApiException(400,"INVALID_EMAIL");int at=value.lastIndexOf('@');return value.substring(0,at)+"@"+value.substring(at+1).toLowerCase(Locale.ROOT);}
 private record Challenge(UUID operation,UUID user,String email,int version,String nonce,Instant issued,Instant expires,String status,boolean retryable,Instant nextRetry,String error){}
 private Challenge challenge(java.sql.ResultSet r,int n)throws java.sql.SQLException{return new Challenge(r.getObject("operation_id",UUID.class),r.getObject("user_id",UUID.class),r.getString("email"),r.getInt("email_version"),r.getString("nonce"),r.getTimestamp("issued_at").toInstant(),r.getTimestamp("expires_at").toInstant(),r.getString("delivery_status"),r.getBoolean("retryable"),instant(r.getTimestamp("next_retry_at")),r.getString("delivery_error"));}
 private Challenge prepare(UUID user){var row=jdbc.queryForMap("SELECT email,email_version,email_verified_at FROM iam.users WHERE id=? FOR UPDATE",user);if(row.get("email")==null)throw new ApiException(400,"EMAIL_REQUIRED");if(row.get("email_verified_at")!=null)throw new ApiException(409,"EMAIL_ALREADY_VERIFIED");
  var current=jdbc.query("SELECT * FROM iam.email_verification_challenges WHERE user_id=? AND email_version=? AND expires_at>? ORDER BY issued_at DESC LIMIT 1",this::challenge,user,row.get("email_version"),java.sql.Timestamp.from(clock.instant()));if(!current.isEmpty())return current.getFirst();
  byte[] nonce=new byte[32];RANDOM.nextBytes(nonce);Challenge c=new Challenge(UUID.randomUUID(),user,(String)row.get("email"),(Integer)row.get("email_version"),Base64.getUrlEncoder().withoutPadding().encodeToString(nonce),clock.instant(),clock.instant().plusSeconds(900),"UNKNOWN",false,null,null);
  jdbc.update("INSERT INTO iam.email_verification_challenges(operation_id,user_id,email,email_version,nonce,token_hash,issued_at,expires_at) VALUES(?,?,?,?,?,?,?,?)",c.operation(),user,c.email(),c.version(),c.nonce(),hash(token(c)),java.sql.Timestamp.from(c.issued()),java.sql.Timestamp.from(c.expires()));audit.enqueue("EMAIL_VERIFICATION_REQUESTED",user,Map.of(),Map.of("verified",false));return c;
 }
 public record Receipt(UUID operationId,String status,boolean retryable,Instant nextRetryAt,String errorCode){}
 public Receipt request(UUID user){Challenge c=tx.execute(s->prepare(user));if(c.status().equals("ACCEPTED"))return receipt(c);
  if(c.nextRetry()!=null&&clock.instant().isBefore(c.nextRetry()))return receipt(c);
  Receipt result;try{Map<String,Object> payload=Map.of("operationId",c.operation().toString(),"userId",user.toString(),"email",c.email(),"token",token(c),"expiresAt",c.expires().toString());var req=HttpRequest.newBuilder(endpoint).timeout(Duration.ofSeconds(4)).header("X-Service-Key",auth.serviceKey()).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(JSON.writeValueAsString(payload))).build();var response=client.send(req,HttpResponse.BodyHandlers.ofString());
   if(response.statusCode()!=200&&response.statusCode()!=202)result=new Receipt(c.operation(),"UNKNOWN",false,null,"VERIFICATION_DELIVERY_UNAVAILABLE");
   else{JsonNode body=JSON.readTree(response.body());String state=body.path("status").asText();if(!c.operation().toString().equals(body.path("operationId").asText())||!Set.of("ACCEPTED","FAILED","NOT_CONFIGURED","UNKNOWN").contains(state))throw new IllegalStateException("Invalid verification receipt");boolean retry=(state.equals("FAILED")||state.equals("NOT_CONFIGURED"))&&body.path("retryable").asBoolean();Instant next=body.path("nextRetryAt").isTextual()?Instant.parse(body.get("nextRetryAt").asText()):null;String code=body.path("errorCode").isTextual()?body.get("errorCode").asText():null;if(code!=null&&!code.matches("[A-Z][A-Z0-9_]{0,63}"))code="VERIFICATION_DELIVERY_UNAVAILABLE";result=new Receipt(c.operation(),state,retry,next,code);}
  }catch(InterruptedException e){Thread.currentThread().interrupt();result=new Receipt(c.operation(),"UNKNOWN",false,null,"VERIFICATION_DELIVERY_UNAVAILABLE");}catch(Exception e){result=new Receipt(c.operation(),"UNKNOWN",false,null,"VERIFICATION_DELIVERY_UNAVAILABLE");}
  Receipt value=result;tx.executeWithoutResult(s->jdbc.update("UPDATE iam.email_verification_challenges SET delivery_status=?,retryable=?,next_retry_at=?,delivery_error=? WHERE operation_id=? AND delivery_status<>'ACCEPTED'",value.status(),value.retryable(),value.nextRetryAt()==null?null:java.sql.Timestamp.from(value.nextRetryAt()),value.errorCode(),value.operationId()));return value;
 }
 private static Receipt receipt(Challenge c){return new Receipt(c.operation(),c.status(),c.retryable(),c.nextRetry(),c.error());}
 public Profile verify(UUID user,String token){return tx.execute(s->{var own=jdbc.queryForMap("SELECT email,email_version FROM iam.users WHERE id=? FOR UPDATE",user);var rows=jdbc.query("SELECT * FROM iam.email_verification_challenges WHERE token_hash=? FOR UPDATE",this::challenge,hash(token));if(rows.isEmpty())throw new ApiException(400,"EMAIL_VERIFICATION_INVALID");Challenge c=rows.getFirst();if(!c.user().equals(user)||!c.email().equals(own.get("email"))||c.version()!=(Integer)own.get("email_version"))throw new ApiException(400,"EMAIL_VERIFICATION_INVALID");Boolean consumed=jdbc.queryForObject("SELECT consumed_at IS NOT NULL FROM iam.email_verification_challenges WHERE operation_id=?",Boolean.class,c.operation());if(Boolean.TRUE.equals(consumed))return profile(user);if(!clock.instant().isBefore(c.expires()))throw new ApiException(400,"EMAIL_VERIFICATION_EXPIRED");
  jdbc.update("UPDATE iam.email_verification_challenges SET consumed_at=? WHERE operation_id=?",java.sql.Timestamp.from(clock.instant()),c.operation());jdbc.update("UPDATE iam.users SET email_verified_at=?,updated_at=now() WHERE id=?",java.sql.Timestamp.from(clock.instant()),user);audit.enqueue("EMAIL_VERIFIED",user,Map.of("verified",false),Map.of("verified",true));return profile(user);
 });}
 private String token(Challenge c){try{String material="FduStudyRoom/email-verification/v1\0"+c.operation()+"\0"+c.user()+"\0"+c.email()+"\0"+c.version()+"\0"+c.nonce()+"\0"+c.expires();Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(auth.serviceKey().getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return Base64.getUrlEncoder().withoutPadding().encodeToString(mac.doFinal(material.getBytes(StandardCharsets.UTF_8)));}catch(GeneralSecurityException e){throw new IllegalStateException("Email verification signing unavailable");}}
 private static String hash(String token){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(token.getBytes(StandardCharsets.UTF_8)));}catch(GeneralSecurityException e){throw new IllegalStateException("Digest unavailable");}}
 public record Address(UUID userId,boolean enabled,String email,boolean verified){}
 public Address address(UUID id){return jdbc.query("SELECT u.id,u.email,u.email_verified_at,u.enabled AND r.enabled AS active FROM iam.users u JOIN iam.roles r ON r.id=u.role_id WHERE u.id=?",(r,n)->new Address(id,r.getBoolean("active"),r.getString("email"),r.getBoolean("active")&&r.getTimestamp("email_verified_at")!=null),id).stream().findFirst().orElseThrow(()->new ApiException(404,"USER_NOT_FOUND"));}
}
